int save_xsave_state(struct xsave_struct *fx, u64 mask) {
    // Use inline assembly to select the appropriate xsave instruction
    // based on feature availability
    // Assume xsaveopt is available (default case)
    __asm__ __volatile__(
        ".ifnidn __k8;\n\t"
        "xsaveopt %0;\n\t"
        ".elseifnidn __k6;\n\t"
        "xsaves %0;\n\t"
        ".else;\n\t"
        "xsave %0;\n\t"
        ".endif"
        : "=m"(*fx)
        : "X"(mask)
        : "memory");

    return 0;
}

int save_xsave_state(struct xsave_struct *fx, u64 mask) {
    // Use the appropriate xsave instruction based on feature availability
    // Inline assembly to handle different xsave alternatives
    asm volatile (
        // Check for xsaves support and use the appropriate instruction
        ".alternative_if_not * .Lnoxsaves\n\t"
        "xsaves %0, %1\n\t"
        ".Lnoxsaves:\n\t"
        "xsave %0, %1\n\t"
        ".alternative_else\n\t"
        "xsaveopt %0, %1\n\t"
        ".alternative_endif"
        : /* no outputs */
        : "m"(*fx), "r"(mask)
        : "memory");

    // Return 0 to indicate success
    return 0;
}

int save_xsave_state(struct xsave_struct *fx, u64 mask) {
    // Determine and invoke the appropriate xsave instruction
    // using inline assembly with alternatives based on CPU features.
    asm volatile(
        ".alternative_if 0b10000000000000000000000000000000\n"
        ".quad xsaves %0, %1\n"
        ".alternative_else\n"
        ".quad xsaveopt %0, %1\n"
        ".alternative_endif"
        :
        : "m"(*fx), "r"(mask)
        : "memory"
    );

    return 0;
}

int save_extended_processor_state(struct xsave_struct *fx, u64 mask) {
    // Use inline assembly alternatives to select the appropriate xsave
    // instruction based on CPU features.
    asm volatile(
        // Alternative for xsaves if supported
        ".alternative_if_not 0x00000000, %c[has_xsaves]\n"
        "xsaves %0, %1\n"
        ".alternative_else\n"
        // Fallback to xsaveopt if xsaves is not available
        "xsaveopt %0, %1\n"
        ".alternative_endif"
        :
        : "m"(*fx), "r"(mask), [has_xsaves]"i"(1 << 29)
        : "memory");

    return 0; // Success
}
